CREATE TABLE content_versions(id text PRIMARY KEY, version text NOT NULL, type text NOT NULL CHECK(type IN ('DEMAND','ORDINARY','LINKED','TIP','SYSTEM')), payload jsonb NOT NULL, checksum text NOT NULL);
CREATE TABLE participants(id uuid PRIMARY KEY, cat_name text, relation_term text NOT NULL DEFAULT '麻麻', status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','ACTIVE')), safety_state text NOT NULL DEFAULT 'CLEAR' CHECK(safety_state IN ('CLEAR','INTERCEPTED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invites(token_hash text PRIMARY KEY, participant_id uuid NOT NULL REFERENCES participants(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE sessions(token_hash text PRIMARY KEY, participant_id uuid REFERENCES participants(id), role text NOT NULL CHECK(role IN ('USER','ADMIN')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK((role='USER')=(participant_id IS NOT NULL)));
CREATE TABLE trips(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES participants(id), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, simulation boolean NOT NULL CHECK(simulation), UNIQUE(id,participant_id));
CREATE UNIQUE INDEX one_active_trip ON trips(participant_id) WHERE ended_at IS NULL;
CREATE TABLE letters(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES participants(id), content_id text NOT NULL REFERENCES content_versions(id), type text NOT NULL CHECK(type IN ('DEMAND','POSTCARD')), snapshot jsonb NOT NULL, trip_id uuid, delivered_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, skipped_at timestamptz, simulation boolean NOT NULL CHECK(simulation), UNIQUE(id,participant_id), UNIQUE(participant_id,content_id), FOREIGN KEY(trip_id,participant_id) REFERENCES trips(id,participant_id), CHECK((type='POSTCARD')=(trip_id IS NOT NULL)));
CREATE UNIQUE INDEX one_postcard_per_trip ON letters(trip_id) WHERE trip_id IS NOT NULL;
CREATE TABLE responses(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES participants(id), letter_id uuid NOT NULL UNIQUE, text text NOT NULL CHECK(length(text) BETWEEN 1 AND 2000), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(participant_id,idempotency_key), FOREIGN KEY(letter_id,participant_id) REFERENCES letters(id,participant_id));
CREATE TABLE safety_cases(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES participants(id), adapter_version text NOT NULL, fixture_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY, participant_id uuid REFERENCES participants(id), event text NOT NULL, object_id text, actor text NOT NULL, simulation boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY, window_at timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
